def bo_sung_du_lieu_cu(apps, schema_editor):
    """Giữ số tiền đã chốt của đơn cũ và lý do từ chối hóa đơn đã ghi."""
    db = schema_editor.connection.alias
    DonHang = apps.get_model("ban_hang", "DonHang")
    ChiTietDonHang = apps.get_model("ban_hang", "ChiTietDonHang")
    ChiTietPhieuBan = apps.get_model("ban_hang", "ChiTietPhieuBan")
    HoaDon = apps.get_model("ban_hang", "YeuCauXuatHoaDon")
    HoaDon.objects.using(db).filter(trang_thai="tu_choi").update(
        ly_do_tu_choi=models.F("ghi_chu_xu_ly")
    )
    for don in DonHang.objects.using(db).filter(giam_gia_thanh_vien__gt=0).iterator():
        cac_dong = list(
            ChiTietDonHang.objects.using(db)
            .filter(don_hang=don)
            .select_related("thuoc")
            .order_by("pk")
        )
        cac_dong_otc = [dong for dong in cac_dong if not dong.thuoc.la_thuoc_ke_don]
        so_tien = int(don.giam_gia_thanh_vien)
        co_so = [int(dong.don_gia * dong.so_luong) for dong in cac_dong_otc]
        if sum(co_so) < so_tien:
            # Danh mục hiện tại có thể đã thay đổi cờ kê đơn so với ngày bán.
            cac_dong_otc = cac_dong
            co_so = [int(dong.don_gia * dong.so_luong) for dong in cac_dong]
        tong = sum(co_so)
        if tong < so_tien:
            raise ValueError(f"Đơn {don.ma_don_hang} có ưu đãi vượt tổng tiền các dòng.")
        cac_phan = [divmod(so_tien * tien, tong) for tien in co_so]
        phan_bo = [phan for phan, _ in cac_phan]
        thu_tu = sorted(range(len(cac_phan)), key=lambda i: cac_phan[i][1], reverse=True)
        for i in thu_tu[: so_tien - sum(phan_bo)]:
            phan_bo[i] += 1
        for dong, giam in zip(cac_dong_otc, phan_bo, strict=True):
            ChiTietDonHang.objects.using(db).filter(pk=dong.pk).update(giam_gia_phan_bo=giam)
            ChiTietPhieuBan.objects.using(db).filter(
                phieu_ban__don_hang=don, thuoc_id=dong.thuoc_id
            ).update(giam_gia_phan_bo=giam)


